mapper.select:
select f.id, f.fault_no, f.equipment_id, e.code as equipment_code,
       e.name as equipment_name, f.fault_type, f.fault_level,
       f.status, f.reporter_id, u.display_name as reporter_name,
       f.reported_at, w.id as work_order_id, w.work_order_no
from fault_record f
join equipment e on e.id = f.equipment_id
join sys_user u on u.id = f.reporter_id
left join work_order w on w.fault_record_id = f.id

    and f.fault_no like concat('%', #{faultNo}, '%')
    and f.equipment_id = #{equipmentId}
    and f.fault_level = #{faultLevel}
    and f.status = #{status}
    and f.reported_at >= #{reportedFrom}
    and f.reported_at < date_add(#{reportedTo}, interval 1 day)
    and f.reporter_id = #{reporterId}
    and w.maintainer_id = #{maintainerId}

order by f.reported_at desc, f.id desc

select exists(select 1 from work_order
              where fault_record_id = #{faultRecordId}
                and maintainer_id = #{maintainerId})

select f.url from biz_attachment b join file_object f on f.id = b.file_id
where b.biz_type = 'FAULT' and b.biz_id = #{faultRecordId}
order by b.sort_no, b.id
